with with_latest as (select s.*, top1.product_cost from suppliers s join lateral (select c.cost as product_cost from products c where c.supplier_id = s.id order by c.launch_date desc, c.id desc limit 1) top1 on true), enriched as (select id, supplier_name, rating, product_cost, sum(rating) over (partition by city order by product_cost, id rows between unbounded preceding and current row) as running_sum_rating, count(rating) over (partition by city order by product_cost, id rows between unbounded preceding and current row) as running_count_rating, min(rating) over (partition by city order by product_cost, id rows between unbounded preceding and current row) as running_min_rating, round(rating / sum(rating) over (partition by country), 4) as rating_share from with_latest), scored as (select *, avg(running_count_rating) over w_part as last4_avg_running_count_rating, sum(running_count_rating) over w_part as last4_sum_running_count_rating, min(running_count_rating) over w_part as last4_min_running_count_rating from enriched window w_part as (order by running_count_rating, id rows between 3 preceding and current row)), with_last as (select s.id, s.rating, s.running_sum_rating, s.running_count_rating, s.running_min_rating, s.rating_share, s.last4_avg_running_count_rating, x.category, x.product_brand from scored s join lateral (select c.category, c.brand as product_brand from products c where c.supplier_id = s.id order by c.price desc, c.id desc limit 1) x on true), cleaned as (select *, case when running_min_rating >= 3.6 then 'High' when running_min_rating >= 1.7 then 'Medium' else 'Low' end as running_min_rating_tier, case when last4_avg_running_count_rating >= 12.6 then 'High' when last4_avg_running_count_rating >= 7.0 then 'Medium' else 'Low' end as last4_avg_running_count_rating_level from with_last where product_brand is distinct from 'Initech' and running_min_rating < 3.5), with_last_suppliers as (select s.*, x.product_category, x.product_stock_qty from cleaned s join lateral (select c.category as product_category, c.stock_qty as product_stock_qty from products c where c.supplier_id = s.id order by c.price desc, c.id desc limit 1) x on true), deduped as (select * from with_last_suppliers qualify row_number() over (partition by product_category order by last4_avg_running_count_rating desc nulls last, id) = 1) select * from (select product_brand, product_category, running_count_rating from deduped) src pivot (avg(running_count_rating) as amount, count(1) as cnt for product_category in ('Sports', 'Fashion'));
